-- Super Gatorlator 64: Albert the Alligator's animations (the hub's NPC host, sgl_npc.lua).
-- His model (actors/albert, generated by tools/actors/make_albert.py) is a skeleton of GEO_ANIMATED_PART joints;
-- ALBERT_JOINTS lists them in the model's depth-first order, which is the order of the animation channels
-- (tools/actors/test_make_albert.py checks the two agree).
--
-- Each animation is a pose function sampled once at load into a vanilla-format keyframe table
-- (smlua_anim_util_register_animation): channels = root translation x, y, z, then rotation x, y, z of every joint.
-- Angles in degrees. Albert faces +Z, so: rotation x > 0 tips a joint's front down (nod, jaw open, lean
-- forward) and swings a hanging limb backward (x < 0 = forward); rotation z > 0 lifts his left arm out to the
-- side (z < 0 lifts his right arm); rotation y turns a joint toward his left.

ALBERT_JOINTS = { "root", "hips", "torso", "head", "jaw", "arm_l", "arm_r", "tail", "leg_l", "leg_r" }

local TAU = 2 * math.pi
local sin, cos, abs, max = math.sin, math.cos, math.abs, math.max

-- t: frame, n: loop length -> phase in radians
local function ph(t, n) return TAU * t / n end

ALBERT_ANIMS = {
    -- standing: breathing, looking around, tail swishing
    idle = { frames = 120, pose = function(t)
        local p = ph(t, 120)
        return {
            ty = 1.2 * sin(2 * p),
            torso = { 1.5 * sin(2 * p), 3 * sin(p), 0 },
            head = { -2 + 2 * sin(2 * p + 1), 14 * sin(p), 3 * sin(p) },
            arm_l = { 4 * sin(p), 0, 3 + 3 * sin(2 * p) },
            arm_r = { -4 * sin(p), 0, -3 - 3 * sin(2 * p) },
            tail = { 0, 16 * sin(2 * p), 0 },
        }
    end },

    -- walking around the Plaza
    walk = { frames = 32, pose = function(t)
        local p = ph(t, 32)
        return {
            ty = 2.5 * abs(cos(p)),
            hips = { 0, -5 * sin(p), 0 },
            torso = { 5, 7 * sin(p), 0 },
            head = { -4, -6 * sin(p), 2 * sin(p) },
            arm_l = { 24 * sin(p), 0, 6 },
            arm_r = { -24 * sin(p), 0, -6 },
            leg_l = { -30 * sin(p), 0, 0 },
            leg_r = { 30 * sin(p), 0, 0 },
            tail = { 0, 24 * sin(p), 0 },
        }
    end },

    -- answering a question: jaw flapping, nodding, gesturing with both hands
    talk = { frames = 30, pose = function(t)
        local p = ph(t, 30)
        return {
            ty = 1.0 * sin(2 * p),
            torso = { 2, 7 * sin(p), 0 },
            head = { 4 * sin(2 * p), 9 * sin(p), 4 * sin(p + 1) },
            jaw = { 11 + 11 * sin(4 * p), 0, 0 },
            arm_l = { -18 + 14 * sin(p + 2), 0, 14 + 6 * sin(2 * p) },
            arm_r = { -40 + 18 * sin(2 * p), 0, -12 },
            tail = { 0, 12 * sin(2 * p), 0 },
        }
    end },

    -- waiting for the answer: hand on his chin, head tilted, tapping his tail
    think = { frames = 60, pose = function(t)
        local p = ph(t, 60)
        return {
            torso = { -2, 0, 0 },
            head = { -8, 6 * sin(p), 12 },
            jaw = { 2, 0, 0 },
            arm_l = { -20, 0, -8 },
            arm_r = { -128, 0, 18 },
            tail = { 0, 10 * sin(2 * p), 0 },
        }
    end },

    -- hello! (a player walks up)
    wave = { frames = 40, pose = function(t)
        local p = ph(t, 40)
        return {
            ty = 1.5 * sin(2 * p),
            torso = { -2, 4 * sin(p), -4 },
            head = { -4, 0, -10 },
            jaw = { 16, 0, 0 },
            arm_l = { 0, 0, 150 + 22 * sin(2 * p) },
            arm_r = { 6, 0, -8 },
            tail = { 0, 20 * sin(2 * p), 0 },
        }
    end },

    -- the Gator Chomp: arms straight out in front, the top arm chomping down on the bottom one
    chomp = { frames = 48, pose = function(t)
        local p = ph(t, 48)
        local open = max(0, sin(3 * p))
        return {
            ty = 3 * open,
            torso = { -3, 0, 0 },
            head = { -6, 0, 0 },
            jaw = { 26 * open, 0, 0 },
            arm_l = { -84, -16, 0 },
            arm_r = { -98 - 34 * open, 16, 0 },
            tail = { 0, 18 * sin(3 * p), 0 },
        }
    end },
}

local function u16_angle(deg) return math.floor(deg * 65536 / 360 + 0.5) & 0xFFFF end
local function u16_units(v) return math.floor(v + 0.5) & 0xFFFF end

-- pose function -> values / index tables (index: { frame count, first value } per channel; a channel that
-- never changes stores one value)
function sgl_albert_keyframes(anim)
    local channels = {}
    local function channel(get)
        local ch = {}
        for t = 0, anim.frames - 1 do ch[t + 1] = get(t) end
        table.insert(channels, ch)
    end
    local poses = {}
    for t = 0, anim.frames - 1 do poses[t] = anim.pose(t) end
    channel(function() return 0 end)
    channel(function(t) return u16_units(poses[t].ty or 0) end)
    channel(function() return 0 end)
    for _, j in ipairs(ALBERT_JOINTS) do
        for axis = 1, 3 do
            channel(function(t)
                local r = poses[t][j]
                return u16_angle(r ~= nil and r[axis] or 0)
            end)
        end
    end
    local values, index = {}, {}
    for _, ch in ipairs(channels) do
        local same = true
        for i = 2, #ch do
            if ch[i] ~= ch[1] then same = false break end
        end
        table.insert(index, same and 1 or #ch)
        table.insert(index, #values)
        if same then
            table.insert(values, ch[1])
        else
            for _, v in ipairs(ch) do table.insert(values, v) end
        end
    end
    return values, index
end

for name, anim in pairs(ALBERT_ANIMS) do
    local values, index = sgl_albert_keyframes(anim)
    anim.id = "sgl_albert_" .. name
    smlua_anim_util_register_animation(anim.id, 0, 0, 0, 0, anim.frames, values, index)
end

-- switch Albert's object to an animation, from its first frame (the caller only calls this on a change)
function sgl_albert_play(o, name)
    local anim = ALBERT_ANIMS[name]
    if o == nil or anim == nil then return end
    smlua_anim_util_set_animation(o, anim.id)
    o.header.gfx.animInfo.animFrame = 0
end
